"use server";

import { generateObject } from "ai";
import { openai } from "@ai-sdk/openai";
import { z } from "zod";
import { getThemeColorDescription } from "./core/config";

const inputSchema = z.object({
  prompt: z.string().min(3).max(200).describe("User's theme description"),
});

const DESCRIPTION = "A 6-digit hex color code. ";

const getColorSchema = (colorKey: string, extraDescription = "") =>
  z
    .string()
    .describe(
      DESCRIPTION + getThemeColorDescription(colorKey) + " " + extraDescription,
    );

const getPaletteSchema = (theme: "light" | "dark") =>
  z.object({
    text: getColorSchema("text", `${theme} theme`),
    "text-2": getColorSchema("text-2", `${theme} theme`),
    "text-3": getColorSchema("text-3", `${theme} theme`),
    "interface-3": getColorSchema("interface-3", `${theme} theme`),
    "interface-2": getColorSchema("interface-2", `${theme} theme`),
    interface: getColorSchema("interface", `${theme} theme`),
    "background-2": getColorSchema("background-2", `${theme} theme`),
    background: getColorSchema("background", `${theme} theme`),
    primary: getColorSchema("primary", `${theme} theme`),
    secondary: getColorSchema("secondary", `${theme} theme`),
    accent: getColorSchema("accent", `${theme} theme`),
    "accent-2": getColorSchema("accent-2", `${theme} theme`),
    "accent-3": getColorSchema("accent-3", `${theme} theme`),
  });

const outputSchema = z.object({
  name: z.string().min(3).describe("Shorty Theme name"),
  light: getPaletteSchema("light").required().describe("Light theme palette"),
  dark: getPaletteSchema("dark").required().describe("Dark theme palette"),
});

export const generateVSCodeThemeAI = async (formData: FormData) => {
  const { prompt } = inputSchema.parse(Object.fromEntries(formData.entries()));
  const result = await generateObject({
    model: openai("gpt-4o-mini"),
    system: `You are an expert Visual Studio Code theme generator. Create visually appealing dark/light themes based on the user's prompt:
  - Use a consistent, limited color palette with complementary colors.
  - Ensure high contrast between background and foreground for readability.
  - Use desaturated colors for large areas, saturated for accents.
  - Always use different colors for light/dark, adjusting saturation and lightness.
  - Color shade order:
  dark: bg > bg-2 > ui > ui-2 > ui-3 > tx-3 > tx-2 > tx
  light: bg < bg-2 < ui < ui-2 < ui-3 < tx-3 < tx-2 < tx
  - For light theme:
      - Never use the same brightness as the dark theme.
      - Reduce lightness to 60% and chroma (0.094) for appealing, readable colors.
      - Ensure bg, bg-2, and all shades are harmonious and not too far apart.
      - UI should be precise and carefully selected.
      - Output as hex codes.`,
    schema: outputSchema,
    prompt,
  });
  const formattedResult = {
    [result.object.name]: {
      light: result.object.light,
      dark: result.object.dark,
    },
  };
  return formattedResult;
};

"use server";

import { Prisma, PrismaClient, ShadcnThemes } from "@prisma/client";
import { sanitizeJsonInput } from "@/lib/utils";
import { Theme } from "@/lib/atoms";
import { revalidatePath } from "next/cache";

const prisma = new PrismaClient();

export async function createTheme(theme: Partial<Theme> & { userId: string }) {
  if (!theme.userId) {
    throw new Error("Unauthorized");
  }

  try {
    const newTheme = await prisma.shadcnThemes.create({
      data: {
        name: theme.name!,
        display_name: theme.displayName,
        User: theme.userId,
        light_scheme: sanitizeJsonInput(theme.light),
        dark_scheme: sanitizeJsonInput(theme.dark),
        //fonts: sanitizeJsonInput(theme.fonts),
        radius: String(theme.radius),
        //space: String(theme.space),
        //shadow: theme.shadow,
        charts: sanitizeJsonInput(theme.charts),
        //icons: theme.icons,
      },
    });

    revalidatePath("/themes");
    return newTheme;
  } catch (error) {
    console.error("Error creating ShadcnTheme:", error);
    throw new Error("Failed to create theme");
  }
}

export async function getThemes(
  page: number = 1,
  limit: number = 20,
  search?: string,
) {
  const where: Prisma.ShadcnThemesWhereInput = search
    ? {
        OR: [
          { name: { contains: search, mode: "insensitive" } },
          { display_name: { contains: search, mode: "insensitive" } },
        ],
      }
    : {};

  const [themes, total] = await Promise.all([
    prisma.shadcnThemes.findMany({
      where,
      skip: (page - 1) * limit,
      take: limit,
      orderBy: { xata_createdat: "desc" },
    }),
    prisma.shadcnThemes.count({ where }),
  ]);

  return {
    themes,
    pagination: {
      currentPage: page,
      totalPages: Math.ceil(total / limit),
      totalItems: total,
    },
  };
}

export async function getThemeById(id: string) {
  try {
    const theme = await prisma.shadcnThemes.findUnique({
      where: { xata_id: id },
    });

    if (!theme) {
      throw new Error("Theme not found");
    }

    return theme as ShadcnThemes;
  } catch (error) {
    console.error("Error fetching ShadcnTheme:", error);
    throw new Error("Failed to fetch theme");
  }
}

export async function updateTheme(
  id: string,
  theme: Partial<ShadcnThemes> & { userId: string },
) {
  if (!theme.userId) {
    throw new Error("Unauthorized");
  }

  try {
    const updatedTheme = await prisma.shadcnThemes.update({
      where: { xata_id: id, User: theme.userId },
      data: {
        name: theme.name,
        display_name: theme.display_name,
        light_scheme: sanitizeJsonInput(theme.light_scheme),
        dark_scheme: sanitizeJsonInput(theme.dark_scheme),
        //fonts: sanitizeJsonInput(theme.fonts),
        radius: theme.radius,
        //space: theme.space,
        //shadow: theme.shadow,
        charts: sanitizeJsonInput(theme.charts),
        //icons: theme.icons,
        //theme_version: { increment: 1 },
      },
    });

    revalidatePath("/themes");
    return updatedTheme as ShadcnThemes;
  } catch (error) {
    console.error("Error updating ShadcnTheme:", error);
    throw new Error("Failed to update theme");
  }
}

export async function deleteTheme(id: string, userId: string) {
  if (!userId) {
    throw new Error("Unauthorized");
  }

  try {
    await prisma.shadcnThemes.delete({
      where: { xata_id: id, User: userId },
    });

    revalidatePath("/themes");
    return { message: "Theme deleted successfully" };
  } catch (error) {
    console.error("Error deleting ShadcnTheme:", error);
    throw new Error("Failed to delete theme");
  }
}

