import { formatTheme, isThemeOwner, sortThemes } from "@/app/utils";
import { auth } from "@clerk/nextjs/server";
import { PrismaClient } from "@prisma/client";
import { notFound } from "next/navigation";

const prisma = new PrismaClient();

export async function getInitialThemes(
  page = 1,
  limit = 20,
  category?: string,
  userId?: string,
) {
  let whereClause: any = {};

  if (category === "all" || !category) {
    whereClause = userId
      ? { OR: [{ is_public: true }, { User: userId }] }
      : { is_public: true };
  } else if (category === "custom") {
    whereClause = userId ? { User: userId } : { id: "none" };
  } else if (category === "community") {
    whereClause = {
      is_public: true,
      category: "user",
      ...(userId && { NOT: { User: userId } }),
    };
  } else {
    whereClause = {
      category,
      ...(userId
        ? { OR: [{ is_public: true }, { User: userId }] }
        : { is_public: true }),
    };
  }

  const themes = await prisma.themes.findMany({
    where: whereClause,
    include: {
      ThemePalettes: true,
      TokenColors: true,
      Users: true,
    },
    orderBy: { xata_createdat: "desc" },
    skip: (page - 1) * limit,
    take: limit + 1,
  });

  const hasMore = themes.length > limit;
  const themesToReturn = themes.slice(0, limit);

  prisma.$disconnect();

  return {
    themes: themesToReturn.map(formatTheme),
    hasMore,
  };
}

export async function getAllThemes() {
  const { userId } = auth();

  let whereClause = {};

  if (userId) {
    whereClause = {
      OR: [
        {
          is_public: true,
        },
        {
          User: userId,
        },
      ],
    };
  } else {
    whereClause = {
      is_public: true,
    };
  }

  const themes = await prisma.themes.findMany({
    where: whereClause,
    include: {
      ThemePalettes: true,
      TokenColors: true,
      Users: true,
    },
  });

  prisma.$disconnect();
  return sortThemes(themes.map(formatTheme));
}

export async function getThemeById(id: string) {
  const { userId } = auth();

  const theme = await prisma.themes.findUnique({
    where: { xata_id: id },
    include: {
      ThemePalettes: true,
      TokenColors: true,
      Users: true,
    },
  });

  if (!theme) {
    notFound();
  }

  const formattedTheme = formatTheme(theme);

  if (!theme.is_public && !isThemeOwner(userId, formattedTheme)) {
    notFound();
  }

  prisma.$disconnect();
  return formatTheme(theme);
}

export async function getUnprotectedThemeById(id: string) {
  const theme = await prisma.themes.findUnique({
    where: { xata_id: id },
    include: {
      ThemePalettes: true,
      TokenColors: true,
      Users: true,
    },
  });

  if (!theme) {
    notFound();
  }

  prisma.$disconnect();
  return formatTheme(theme);
}

import type { NextApiRequest, NextApiResponse } from "next";
import fs from "fs";
import path from "path";
import { createVSIX } from "@vscode/vsce";
import { generateVSCodeTheme } from "@/lib/core";
import { ThemeConfig } from "@/lib/core/types";

const allowedOrigins = ["http://localhost:3000", "https://tinte.railly.dev"];

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  const origin = req.headers.origin;
  const isAllowed = allowedOrigins.includes(origin as string);

  const headers = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": isAllowed ? origin : "*",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type",
  };

  if (req.method === "OPTIONS") {
    res.writeHead(200, headers).end();
    return;
  }

  if (req.method !== "POST") {
    res
      .writeHead(405, headers)
      .end(JSON.stringify({ error: "Method not allowed" }));
    return;
  }

  if (req.headers["content-type"] !== "application/json") {
    res
      .writeHead(400, headers)
      .end(JSON.stringify({ error: "Unsupported content type" }));
    return;
  }

  let parsedBody;
  try {
    parsedBody = req.body;
  } catch (jsonError) {
    console.error("JSON parsing error:", jsonError);
    res.writeHead(400, headers).end(JSON.stringify({ error: "Invalid JSON" }));
    return;
  }

  const { themeConfig, isDark } = parsedBody;

  try {
    const vsixBuffer = await createVSIXFile(themeConfig, isDark);
    const base64VsixBuffer = vsixBuffer.toString("base64");

    res
      .status(200)
      .setHeader(
        "Access-Control-Allow-Origin",
        headers["Access-Control-Allow-Origin"] as string
      )
      .setHeader(
        "Access-Control-Allow-Methods",
        headers["Access-Control-Allow-Methods"] as string
      )
      .setHeader(
        "Access-Control-Allow-Headers",
        headers["Access-Control-Allow-Headers"] as string
      )
      .setHeader("Access-Control-Allow-Methods", "POST, OPTIONS")
      .setHeader("Access-Control-Allow-Headers", "Content-Type")
      .setHeader("Content-Type", "application/octet-stream")
      .setHeader(
        "Content-Disposition",
        `attachment; filename="${themeConfig.displayName.toLowerCase().replace(/\s+/g, "-")}-${isDark ? "dark" : "light"}-0.0.1.vsix"`
      )
      .send(base64VsixBuffer);
  } catch (error: any) {
    console.error("Error creating VSIX file:", error);
    res.status(500).json({ error: error.message });
  }
}

async function createVSIXFile(themeConfig: ThemeConfig, isDark: boolean) {
  const theme = generateVSCodeTheme(themeConfig);

  // Define paths
  const themePath = path.join(process.cwd(), "temp-theme");
  const packageJsonPath = path.join(themePath, "package.json");
  const themeJsonPath = path.join(themePath, "themes", "theme.json");
  const readmePath = path.join(themePath, "README.md");

  // Ensure the directories exist
  fs.mkdirSync(path.join(themePath, "themes"), { recursive: true });

  // Write package.json
  const packageJson = {
    name: themeConfig.displayName.toLowerCase().replace(/\s+/g, "-"),
    displayName: themeConfig.displayName,
    description: "A customizable VSCode theme",
    publisher: "RaillyHugo",
    version: "0.0.2",
    engines: {
      vscode: "^1.70.0",
    },
    categories: ["Themes"],
    contributes: {
      themes: [
        {
          label: themeConfig.displayName,
          uiTheme: isDark ? "vs-dark" : "vs",
          path: "./themes/theme.json",
        },
      ],
    },
  };

  fs.writeFileSync(
    readmePath,
    `<h3 align="center">
  <img src="https://raw.githubusercontent.com/Railly/website/main/public/images/private-github/tinte-logo.png" width="100" alt="Tinte Logo"/><br/>
